<style scoped lang="scss" src="./section.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import {
  SectionMode,
  SectionModeValues,
  SectionSize,
  SectionSizeValues,
  SectionAlign,
  SectionAlignValues,
  SectionPaddingSize,
  SectionPaddingSizeValues,
} from "./section.constants";
import DesktopOnly from "../desktop-only/desktop-only";
import MobileOnly from "../mobile-only/mobile-only";

/**
 * This does some simple styling to a group of components to make them fit
 * appropriately on the page.
 */
@Component({
  components: {
    DesktopOnly,
    MobileOnly,
  },
})
export default class Section extends Vue {
  /** Rendering mode of the section */
  @Prop({
    type: String,
    default: SectionMode.LIGHT,
    validator: has(SectionModeValues),
  })
  mode;
  /** Desktop size controls of the section */
  @Prop({
    type: String,
    default: SectionSize.LARGE,
    validator: has(SectionSizeValues),
  })
  size;
  /** Mobile sizing of the section */
  @Prop({
    type: String,
    validator: has(SectionSizeValues),
  })
  mobileSize;
  @Prop({
    type: String,
    default: SectionAlign.LEFT,
    validator: has(SectionAlignValues),
  })
  align;
  @Prop({
    type: Boolean,
    default: false,
  })
  roundCorner;
  @Prop({
    type: String,
    default: SectionPaddingSize.LARGE,
    validator: has(SectionPaddingSizeValues)
  })
  paddingSize;

  get mobileSizeClass() {
    return this.mobileSize || this.size;
  }

  get roundCornerStyle() {
    if (this.roundCorner) {
      return {
        borderRadius: "8px"
      }
    }

    return {};
  }
}
</script>

<template>
  <div :class="['Section', mode]" :style="roundCornerStyle">
    <DesktopOnly :media="1024">
      <div :class="['Section__Content', size, align, paddingSize]">
        <slot />
      </div>
    </DesktopOnly>
    <MobileOnly :media="1024">
      <div :class="['Section__Content', mobileSizeClass, align]">
        <slot />
      </div>
    </MobileOnly>
  </div>
</template>
